def solution(input_str):
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    clauses = []
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        ki = parts[0]
        literals = parts[1:]
        clauses.append(literals)

    # Track occurrences of each variable (1-based index)
    # pos[var] = set of literals where var appears (with or without negative)
    var_occurrences = {i+1: [] for i in range(m)}

    for clause in clauses:
        for lit in clause:
            var = abs(lit)
            var_occurrences[var].append(lit)

    # Check constraint: each variable appears at most 2 times
    for var in range(1, m+1):
        if len(var_occurrences[var]) > 2:
            # Should not happen per problem statement, but handle just in case
            pass

    # For CNF, we need ALL clauses to be satisfied (at least one literal true per clause)
    # We'll use backtracking with the constraint that each variable appears ≤ 2 times

    assignment = [False] * (m + 1)  # 1-indexed
    satisfiableClauses = [False] * n

    def is_lit_satisfied(lit, var_assignments):
        var = abs(lit)
        val = var_assignments[var]
        return (lit > 0 and val) or (lit < 0 and not val)

    def solve(idx):
        if idx == n:
            return True

        clause_lits = clauses[idx]

        # Try all possible assignments of variables not yet assigned
        assigned_vars = {i for i in range(1, m+1) if assignment[i]}

        # Check if clause can be satisfied with current assignment
        satisfied = any(is_lit_satisfied(l, assignment) for l in clause_lits)
        if satisfied:
            return solve(idx + 1)

        # Variable to satisfy the clause
        for lit in clause_lits:
            var = abs(lit)
            if var not in assigned_vars:
                # Try setting this variable to satisfy this literal
                orig_val = assignment[var]
                assignment[var] = (lit > 0)
                satisfiableClauses[idx] = True

                if solve(idx + 1):
                    return True

                # Backtrack
                assignment[var] = orig_val
                satisfiableClauses[idx] = False

        return False

    if solve(0):
        return "YES\n" + "".join("1" if assignment[i] else "0" for i in range(1, m+1))
    else:
        return "NO\n"

