        # If competitor i can possibly win, compute the range of S/R ratios

        # For each other competitor j, find the constraint on S/R
        # We want S/s[i] + R/r[i] <= S/s[j] + R/r[j]
        # S(1/s[i] - 1/s[j]) <= R(1/r[i] - 1/r[j])

        for j in range(n):
            if i == j:
                continue

            # If s[i] > s[j] and r[i] >= r[j], constraint is always satisfied
            # If s[i] < s[j] and r[i] <= r[j], constraint never satisfied (i loses to j)

            if s[i] == s[j] and r[i] == r[j]:
                continue

            if s[i] == s[j]:
