            # General case: both s and r differ

            lhs = 1/s[i] - 1/s[j]
            rhs = 1/r[i] - 1/r[j]

            # S * lhs <= R * rhs
            # S/R * lhs <= rhs
            # If lhs > rhs positive: S/R <= rhs/lhs
            # If lhs < rhs negative: S/R >= rhs/lhs

            if lhs > 0:
                if rhs >= 0:
