            elif lhs < 0:
                if rhs <= 0:
                    # rhs/lhs >= 0, so S/R >= rhs/lhs
                    bottom = rhs / lhs
                    if bottom > max_s_ratio:
                        max_s_ratio = bottom
                else:
                    # rhs > 0, lhs < 0, so rhs/lhs < 0, S/R >= negative (always true for positive S,R)
                    continue
            else:
                # lhs == 0, already handled above

        if possible:
            # Check if there's a valid range
            if min_s_ratio < float('inf') and max_s_ratio > -float('inf'):
