def solution(input_data):
    """
    Solves the problem of partitioning a tree into connected states where 
    exactly one state has exactly k towns, minimizing the number of edges 
    between different states (problem roads).
    """
    n, k = map(int, input_data.split('\n')[0].split())
    if n == 1:
        return '0\n'

    edges = []
    for line in input_data.split('\n')[1:]:
        if line:
            u, v = map(int, line.split())
            edges.append((u, v))

    adj = [[] for _ in range(n + 1)]
    parent = [0] * (n + 1)
    order = []

    for i, (u, v) in enumerate(edges):
        adj[u].append((v, i + 1))
        adj[v].append((u, i + 1))

    vis = [False] * (n + 1)
    stack = [1]
    order.append(1)
    vis[1] = True
    p = [-1] * (n + 1)

    while stack:
        u = stack.pop()
        for v, idx in adj[u]:
            if not vis[v]:
                vis[v] = True
                p[v] = u
                stack.append(v)
                order.append(v)
                order.insert(0, v)

    order.reverse()

    inf = float('inf')

    def solve():
        memo = {}

        def dp(u, status, s):
            key = (u, status, s)
            if key in memo:
                return memo[key]

            res = inf
            need = 0
            has_path = False

            if status == 1 and s == k:
                need = 1
                path = True
            else:
                need = 0
                path = (status == 1)

            for v, idx in adj[u]:
                if v == p[u]:
                    continue

                sub, substatus, subs = dp(v, status, s)

                if v < 1 or v > n:
                    continue

                for rv in range(-150, k + 1):
                    if sub == inf and rv != -1:
                        continue

                    if has_path and not sub:
                        continue

                    if rv == -1 and not path:
                        continue

                    cut = 0
                    if rv != -1 and s != k and not path:
                        cut = 1

                    if path and rv == -1:
                        cut = 1

                    total = sub + (depth[u] if path else 0) + cut
                    if total < res:
                        res = total

                memo[(u, status, s)] = res
                return res

        return dp(1, 0, 0)

    result = solve()
    return f"{result}\n"

