import math

def solution(s):
    n, m = map(int, s.strip().split())

    # If either dimension is very small, we can't form pairs with Manhattan distance 3
    if n < 3 or m < 3:
        return "0"

    # For boards with both dimensions >= 3, most cells can be paired
    total_cells = n * m

    # When n and m are both >= 3, we can form pairs for most cells
    # The answer is total_cells // 2 (each pair contributes 2 chessmen)
    # But we need to cap it at total_cells
    if total_cells // 2 * 2 <= total_cells:
        return str(total_cells)

    return str(math.min(total_cells, total_cells // 2))

