def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    components = []

    # Find connected components using DFS
    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(size)

    # Generate lucky numbers (only digits 4 and 7)
    lucky_numbers = []
    def generate_lucky(current, length):
        if current > 0 and current <= 2 * n + 100000:
            lucky_numbers.append(current)
        if length < 12:  # Enough digits for our range
            for digit in [4, 7]:
                generate_lucky(current * 10 + digit, length + 1)

    generate_lucky(0, 0)
    lucky_numbers = sorted(set(lucky_numbers))

    # Sort components in descending order for better pruning
    components.sort(reverse=True)

    # DP: dp[sum] = minimum number of components to get this sum
    dp = {0: 0}

    best = float('inf')

    for size in components:
        # Create new dict to avoid modification issues
        new_dp = dp.copy()

        for s, count in list(dp.items()):
            new_sum = s + size
            if new_sum in lucky_numbers:
                new_count = count + 1
                if new_count < best:
                    best = new_count
            elif new_sum not in dp:
                c = new_count if new_count < best else float('inf')
                new_dp[new_sum] = c
            else:
                existing = dp[new_sum]
                if new_count < existing:
                    new_dp[new_sum] = new_count

        # Trim large dp table to avoid memory issues
        if len(new_dp) > 10000:
            dp = {}
            for s, c in new_dp.items():
                if c < best:
                    dp[s] = c

        dp = new_dp

    if best == float('inf'):
        return "-1\n"
    else:
        return f"{best - 1}\n"


