    for x in arr:
        if x != -1:
            present.add(x)

    # Find missing values (values from 1 to n that don't appear in the array)
    missing = [x for x in range(1, n + 1) if x not in present]
    k = len(missing)  # number of -1 positions

    # Count "bad" positions: positions with -1 where position value (i+1) is missing
    # These positions must NOT receive their natural value to avoid fixed points
    bad = 0
    for i in range(n):
        if arr[i] == -1:
            if (i + 1) in missing:
                bad += 1

    mod = 1000000007

    # Precompute factorials up to k
    fact = [1] * (k + 1)
    for i in range(1, k + 1):
        fact[i] = (fact[i - 1] * i) % mod

    # Precompute combinations C(bad, i) using Pascal's triangle
    C = [[0] * (bad + 1) for _ in range(bad + 1)]
    for i in range(bad + 1):
        C[i][0] = 1
        for j in range(1, i + 1):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % mod

    # Use inclusion-exclusion principle
    # Answer = sum_{i=0 to bad} (-1)^i * C(bad, i) * (k - i)!
    # This counts ways where i bad positions get their forbidden value (to be subtracted/added)
    ans = 0
    for i in range(bad + 1):
        term = (C[bad][i] * fact[k - i]) % mod
        if i % 2 == 1:
            ans = (ans - term + mod) % mod
        else:
            ans = (ans + term) % mod

    return str(ans)

