def is_axis_square(grid, r1, c1, size):
    n, m = len(grid), len(grid[0]) if grid else 0

    r2, c2 = r1 + size - 1, c1 + size - 1

    # Check frame cells are all '1'
    # Top and bottom rows
    for c in range(c1, c2 + 1):
        if grid[r1][c] != '1' or grid[r2][c] != '1':
            return False

    # Left and right columns
    for r in range(r1 + 1, r2):
        if grid[r][c1] != '1' or grid[r][c2] != '1':
            return False

    # Check no foreign '1's touch the frame
    # A cell is on the frame if it's in the boundary of the square
    for r in range(r1 - 1, r2 + 2):
        for c in range(c1 - 1, c2 + 2):
            if not (0 <= r < n and 0 <= c < m):
