                if not is_frame:
                    return False  # Foreign 1 found touching the square

    return True


def get_diagonal_frame_cells(r, c, arm):
    """
    For a diagonal square, the frame forms a diamond shape.
    The arm is the maximum number of cells from the center in either direction
    along the diagonal.
    Points on the frame satisfy: max(|x-r|, |y-c|) == arm in one rotated coordinate system,
    or equivalently, max(|r+y-x|, |r-y+x|) == something transforms to the rotated frame.

    For practical purposes: the frame consists of points where
    EITHER (row increases by 1, col increases by 1) arm times OR similar diagonal moves,
    forming a 45-degree rotated square boundary.
    """
    frame = []
    arm_sq = arm * arm  # arm squared for Manhattan distance check

    # A diagonal square of "arm" has frame at Manhattan distance arm from center
    # in one time, OR we use rotated coordinate check
    for dr in range(-arm, arm + 1):
        for dc in range(-arm, arm + 1):
            nr, nc = r + dr, c + dc
            # Check if this forms a diamond frame (Manhattan distance from center)
            if max(abs(dr), abs(dc)) == arm:
                frame.append((nr, nc))

    return frame


def is_diagonal_square(grid, rc, cc, arm):
    n, m = len(grid), len(grid[0]) if grid else 0

    if arm == 0:
        return False

    frame = get_diagonal_frame_cells(rc, cc, arm)

