    n, m = d[0], d[1]
    if m == n - 1:
        return ""

    idx = 2
    edges = []
    for i in range(m):
        a, b, e = d[idx], d[idx+1], d[idx+2]
        idx += 3
        edges.append((a - 1, b - 1, e, i))

    # Union-Find for MST construction
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def unite(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    # Build MST using Kruskal's algorithm
    mst_edges = set()
    mst_weight = {}
    sorted_edges = sorted(edges, key=lambda x: x[2])

    for u, v, w, i in sorted_edges:
        if unite(u, v):
            mst_edges.add(i)
            mst_weight[i] = w

    if len(mst_edges) == 0:
        return ""

    # Build adjacency list for MST
    adj = [[] for _ in range(n)]
    for i in mst_edges:
        u, v, w, _ = edges[i]
        adj[u].append((v, w))
        adj[v].append((u, w))

    # BFS for level and parent computation
    level = [0] * n
    up = [[0] * 20 for _ in range(n)]  # up[i][j] is 2^j-th ancestor of i
    max_on_path = [[0] * 20 for _ in range(n)]  # max weight on path to 2^j-th ancestor

    visited = [False] * n
    queue = [0]
    visited[0] = True
    level[0] = 0
    up[0][0] = 0

    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1

        for v, w in adj[u]:
            if not visited[v]:
                visited[v] = True
                level[v] = level[u] + 1
                up[v][0] = u
                max_on_path[v][0] = w
                queue.append(v)

    # Build doubling table
    for j in range(1, 20):
        for i in range(n):
            if up[i][j-1] != 0:
                up[i][j] = up[up[i][j-1]][j-1]
                max_on_path[i][j] = max(max_on_path[i][j-1], max_on_path[up[i][j-1]][j-1])
            else:
                up[i][j] = 0
                max_on_path[i][j] = max_on_path[i][j-1]

    # Query function to get max weight on path between u and v in MST
    def query(u, v):
        res = 0

        # Equalize depths
        diff = level[u] - level[v]
        for j in range(19, -1, -1):
            if diff & (1 << j):
                res = max(res, max_on_path[u][j])
                u = up[u][j]

        if u == v:
            return res

        # Lift both until just below LCA
        for j in range(19, -1, -1):
            if up[u][j] != up[v][j]:
                res = max(res, max_on_path[u][j])
                res = max(res, max_on_path[v][j])
                u = up[u][j]
                v = up[v][j]

        # Final step to LCA
        res = max(res, max_on_path[u][0])
        res = max(res, max_on_path[v][0])
        return res

    # Build output
    result = []
    for u, v, w, i in edges:
        if i not in mst_edges:
            result.append(str(query(u, v)))

    return '\n'.join(result)

