def solution(input_str):
    tokens = input_str.replace('\n', ' ').split()
    if not tokens:
        return ""

    iterator = iter(tokens)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return ""

    # Build adjacency list with edge indices
    adj = [[] for _ in range(n + 1)]

    for edge_idx in range(1, m + 1):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            w = int(next(iterator))
            adj[u].append((v, w, edge_idx))
            adj[v].append((u, w, edge_idx))
        except StopIteration:
            break

    # Get start vertex
    try:
        start_node = int(next(iterator))
    except StopIteration:
        return ""

    # Dijkstra's algorithm to find shortest distances
    dist = [float('inf')] * (n + 1)
    dist[start_node] = 0
    pq = [(0, start_node)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w, idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # For each vertex (except start), find the minimum weight edge
    # that lies on a shortest path from start_node to this vertex
    total_weight = 0
    selected_edges = []

    for v in range(1, n + 1):
        if v == start_node:
            continue

        min_w = float('inf')
        best_idx = -1

        for u, w, idx in adj[v]:
            # Check if edge (u, v) lies on a shortest path to v
            if dist[u] + w == dist[v]:
                if w < min_w:
                    min_w = w
                    best_idx = idx

        if best_idx != -1:
            total_weight += min_w
            selected_edges.append(best_idx)

    # Sort edge indices for consistent output
    selected_edges.sort()

    return str(total_weight) + '\n' + ' '.join(map(str, selected_edges))

