    N, M, K = int(first_line[0]), int(first_line[1]), int(first_line[2])

    if N == 0 or M == 0:
        return '0\n'

    transformers = []
    for i in range(1, min(K + 1, len(lines))):
        parts = lines[i].split()
        if len(parts) >= 5:
            x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
            transformers.append((x, y, d, t, e))

    # Map each cell to energy cost (at arrival time)
    # key: (i, j), value: energy cost
    cell_cost = defaultdict(int)

    for x, y, d, t, e in transformers:
        # The transformer jumps through 4 positions in cycle
        # Position at time T (T >= t):
        #   T==t: (x,y)
        #   T==t+1: (x+d, y-d)
        #   T==t+2: (x+d, y)
        #   T==t+3: (x, y+d)
        #   T==t+4: (x,y) - cycle repeats

        for phase in range(4):
            arrive_time = t + phase
            if arrive_time < 0:
                continue

            # Calculate position at this phase
            if phase == 0:
                px, py = x, y
            elif phase == 1:
                px, py = x + d, y - d
            elif phase == 2:
                px, py = x + d, y
            else:  # phase == 3
                px, py = x, y + d

            # To meet the transformer, we must arrive at (px, py) at exactly arrive_time
            # Since row i + col j = arrival time from (0,0)
            if px + py == arrive_time and 0 <= px < N and 0 <= py < M:
                cell_cost[(px, py)] += e

    # DP: minimum energy to reach each cell
    INF = float('inf')
    dp = [[INF] * M for _ in range(N)]
    dp[0][0] = cell_cost.get((0, 0), 0)

    for i in range(N):
        for j in range(M):
            if i == 0 and j == 0:
                continue

            cost = cell_cost.get((i, j), 0)

            from_top = dp[i-1][j] if i > 0 else INF
            from_left = dp[i][j-1] if j > 0 else INF

            dp[i][j] = min(from_top, from_left) + cost

    return str(dp[N-1][M-1]) + '\n'


