def is_gp(seq):
    """Check if a sequence is a geometric progression."""
    # Sequences with 2 or fewer elements are always valid GPs
    if len(seq) <= 2:
        return True

    n = len(seq)
    # Check consecutive triplets: for geometric progression, b^2 = a*c
    # This handles all cases including zeros correctly
    for i in range(n - 2):
        if seq[i+1] ** 2 != seq[i] * seq[i+2]:
            return False
    return True

