def find_mst_weight(n, pre_edges):
    import sys
    from typing import Tuple

    class DSU:
        def __init__(self, n):
            self.parent = list(range(n))
            self.rank = [0] * n

        def find(self, x):
            if self.parent[x] != x:
                self.parent[x] = self.find(self.parent[x])
            return self.parent[x]

        def union(self, x, y):
            px, py = self.find(x), self.find(y)
            if px == py:
                return False
            if self.rank[px] < self.rank[py]:
                px, py = py, px
            self.parent[py] = px
            if self.rank[px] == self.rank[py]:
                self.rank[px] += 1
            return True

    def build_mst(u_from_v_to_w):
        edges = []
        uvw_tuples = list(map(tuple, u_from_v_to_w))
        for u, v, w in uvw_tuples:
            edges.append((w, u - 1, v - 1))
        edges.sort()

        dsu = DSU(n)
        total = 0
        edges_count = 0

        for w, u, v in edges:
            if dsu.union(u, v):
                total += w
                edges_count += 1
                if edges_count == n - 1:
                    break

        if edges_count < n - 1:
            return float('inf')
        return total

    return build_mst(pre_edges)

